public class Main {
    static int clamp(int value, int lower, int upper) {
        if (value < lower) {
            return lower;
        } else if (value > upper) {
            return upper;
        } else {
            return value;
        }
    }
    public static void main(String[] args) {
        System.out.println(clamp(101, 0, 100));
    }
}

